<?php
require_once __DIR__.'/includes/db.php';require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/permissions.php';require_once __DIR__.'/includes/icons.php';require_once __DIR__.'/includes/novedades_semanales_common.php';
auth_require();permissions_require_menu('novedades_semanales_seguimiento');$cfg=require __DIR__.'/config.php';date_default_timezone_set($cfg['app']['tz']??'UTC');$APP_USER=auth_user();$APP_ROLE=auth_es_admin()?'Administrador':'Operador';$ACTIVE='novedades_semanales_seguimiento';
$db=clear_db();$ready=ns_module_ready($db);$commentsReady=$ready&&ns_comments_ready($db);$reportReady=$ready&&ns_report_ready($db);$today=new DateTimeImmutable('now');$prefs=ns_preferences();$period=ns_period($_GET,$today,$prefs);$scope=strtolower(ns_clean($_GET['estado']??'sin',10));if(!in_array($scope,['todos','con','sin'],true))$scope='sin';$q=ns_clean($_GET['q']??'',220);$type=ns_clean($_GET['tipo_instalacion']??'',30);if($type!==''&&!array_key_exists($type,ns_type_options()))$type='';$rows=[];$allCount=0;$withCount=0;$withoutCount=0;$updated='';$canUseComments=$commentsReady&&(permissions_can('comments.view')||permissions_can('comments.create'));
if($ready&&$commentsReady){$baseParams=[$period['from_value'],$period['to_value']];$baseWhere=['C.SEMANA_DESDE>=CONVERT(date,?,23)','C.SEMANA_DESDE<=CONVERT(date,?,23)'];if($type!==''){$baseWhere[]='C.TIPO_INSTALACION=?';$baseParams[]=$type;}if($q!==''){$baseWhere[]='(C.INSTALACION LIKE ? OR C.TAG LIKE ? OR C.DESCRIPCION LIKE ? OR C.CAMPO_EXT LIKE ? OR CO.COMENTARIO LIKE ?)';for($i=0;$i<5;$i++)$baseParams[]='%'.$q.'%';}$base='FROM dbo.CLEAR_NOVEDADES_SEMANALES_CACHE C LEFT JOIN dbo.CLEAR_NOVEDADES_SEMANALES_COMENTARIOS CO ON CO.SEMANA_DESDE=C.SEMANA_DESDE AND CO.TIPO_INSTALACION=C.TIPO_INSTALACION AND CO.INSTALACION=C.INSTALACION AND CO.TAG=C.TAG WHERE '.implode(' AND ',$baseWhere);$allCount=(int)$db->scalar("SELECT COUNT_BIG(*) $base",$baseParams);$withCount=(int)$db->scalar("SELECT COUNT_BIG(*) $base AND CO.ACTIVO=1 AND CO.COMENTARIO<>N''",$baseParams);$withoutCount=max(0,$allCount-$withCount);$scopeSql=$scope==='con'?" AND CO.ACTIVO=1 AND CO.COMENTARIO<>N''":($scope==='sin'?" AND (CO.ID IS NULL OR CO.ACTIVO=0 OR CO.COMENTARIO=N'')":'');$rows=$db->all("SELECT TOP 500 ".ns_cache_select('C').",CO.COMENTARIO,CO.ACTIVO COMENTARIO_ACTIVO,CO.USUARIO_CARGA,CO.USUARIO_MODIFICACION,CONVERT(varchar(19),CO.FECHA_CARGA,120) FECHA_CARGA,CONVERT(varchar(19),CO.FECHA_MODIFICACION,120) FECHA_MODIFICACION $base$scopeSql ORDER BY C.TOTAL_ALARMAS DESC,C.INSTALACION,C.TAG",$baseParams);$updated=(string)$db->scalar("SELECT CONVERT(varchar(19),MAX(FECHA_ACTUALIZACION),120) FROM dbo.CLEAR_NOVEDADES_SEMANALES_CACHE WHERE SEMANA_DESDE BETWEEN CONVERT(date,?,23) AND CONVERT(date,?,23)",[$period['from_value'],$period['to_value']]);}$coverage=$allCount?$withCount/$allCount*100:0;
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Seguimiento · Novedades semanales</title><link rel="stylesheet" href="assets/css/app.css?v=20260826-ns3"><link rel="stylesheet" href="assets/css/novedades_semanales.css?v=20260826-report-common-1"></head><body><div class="app"><?php include __DIR__.'/includes/sidebar.php'; ?><main class="main"><?php include __DIR__.'/includes/topbar.php'; ?>
<div class="page__head nsHead"><div><h1 class="page__title">Seguimiento semanal</h1><div class="page__sub">Control de malos actores justificados y pendientes, con búsqueda, orden y exportación.</div></div><div class="page__live"><span class="dot"></span><?php echo $ready?'Seguimiento activo':'Requiere instalación'; ?></div></div><?php ns_render_module_nav($ACTIVE); ?>
<?php if(!$ready):ns_render_not_installed();elseif(!$commentsReady): ?><div class="nsNotice is-warning">Falta la tabla de comentarios. Volvé a ejecutar <code>SQL/CLEAR_NOVEDADES_SEMANALES.sql</code>.</div><?php else: ?><form class="nsToolbar" method="get"><label class="nsControl"><span>Semana desde</span><input type="date" name="desde" value="<?php echo h($period['from_value']); ?>"></label><label class="nsControl"><span>Semana hasta</span><input type="date" name="hasta" value="<?php echo h($period['to_value']); ?>"></label><label class="nsControl"><span>Estado</span><select name="estado"><option value="sin" <?php echo $scope==='sin'?'selected':''; ?>>Pendientes</option><option value="con" <?php echo $scope==='con'?'selected':''; ?>>Con comentario</option><option value="todos" <?php echo $scope==='todos'?'selected':''; ?>>Todos</option></select></label><label class="nsControl"><span>Tipo</span><select name="tipo_instalacion"><option value="">Todos</option><?php foreach(ns_type_options() as $v=>$l): ?><option value="<?php echo h($v); ?>" <?php echo $type===$v?'selected':''; ?>><?php echo h($l); ?></option><?php endforeach; ?></select></label><label class="nsControl nsControl--wide"><span>Buscar</span><input name="q" value="<?php echo h($q); ?>" placeholder="Instalación, TAG, descripción, campo o comentario"></label><button class="nsButton" type="submit">Aplicar</button><a class="nsButton is-secondary" href="novedades_semanales_export.php?vista=seguimiento&amp;<?php echo h(ns_query_string()); ?>"><?php echo icon('download'); ?> Excel</a><a class="nsButton is-secondary" href="novedades_semanales_reporte.php">Reporte <span class="nsReportCount" data-ns-report-count hidden>0</span></a></form>
<section class="nsStats"><article class="nsStat"><div class="nsStat__label">Actores de la selección</div><div class="nsStat__value"><?php echo ns_num($allCount); ?></div><div class="nsStat__detail"><?php echo h(ns_period_label($period)); ?></div></article><article class="nsStat is-green"><div class="nsStat__label">Documentados</div><div class="nsStat__value"><?php echo ns_num($withCount); ?></div><div class="nsStat__detail">Con justificación activa.</div></article><article class="nsStat is-red"><div class="nsStat__label">Pendientes</div><div class="nsStat__value"><?php echo ns_num($withoutCount); ?></div><div class="nsStat__detail">Requieren revisión o comentario.</div></article><article class="nsStat is-amber"><div class="nsStat__label">Cobertura</div><div class="nsStat__value"><?php echo ns_percent($coverage); ?></div><div class="nsStat__detail">Avance del período seleccionado.</div></article></section>
<section class="nsTableCard"><div class="nsTableHead"><div><h2><?php echo $scope==='sin'?'Pendientes de justificación':($scope==='con'?'Comentarios semanales':'Seguimiento completo'); ?></h2><p>Hasta 500 filas. Ordená o filtrá localmente cada columna.</p></div><div class="nsTableMeta">Actualizado: <b><?php echo h($updated?:'sin datos'); ?></b></div></div><div class="tablescroll"><table class="grid nsTable" id="nsTrackingTable"><thead><tr><th>REPORTE</th><?php $heads=[['SEMANA','text'],['TIPO','text'],['INSTALACIÓN','text'],['TAG','text'],['DESCRIPCIÓN','text'],['TOTAL','number'],['CAMPO EXT.','text'],['COMENTARIO','text'],['ÚLTIMA GESTIÓN','text']];foreach($heads as $i=>$head): ?><th><button class="nsClientSort" data-ns-sort-client data-table="nsTrackingTable" data-column="<?php echo $i+1; ?>" data-kind="<?php echo h($head[1]); ?>"><?php echo h($head[0]); ?></button></th><?php endforeach; ?></tr><tr class="nsFilterRow"><th></th><th><input data-ns-client-filter data-table="nsTrackingTable" data-column="1" placeholder="Semana"></th><th><select data-ns-client-filter data-table="nsTrackingTable" data-column="2"><option value="">Todos</option><?php foreach(ns_type_options() as $v=>$l): ?><option value="<?php echo h($v); ?>"><?php echo h($l); ?></option><?php endforeach; ?></select></th><?php for($i=3;$i<=9;$i++): ?><th><input data-ns-client-filter data-table="nsTrackingTable" data-column="<?php echo $i; ?>" placeholder="Buscar"></th><?php endfor; ?></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="10" class="nsEmpty">No existen filas para el estado seleccionado.</td></tr><?php else:foreach($rows as $row):$start=ns_parse_date(ns_value($row,'SEMANA_DESDE'));$weekLabel=$start?ns_week_label($start):'';$comment=trim((string)ns_value($row,'COMENTARIO'));$user=(string)(ns_value($row,'USUARIO_MODIFICACION')?:ns_value($row,'USUARIO_CARGA'));$saved=(string)(ns_value($row,'FECHA_MODIFICACION')?:ns_value($row,'FECHA_CARGA'));$payload=ns_report_row_payload(['Semana'=>$weekLabel,'Tipo'=>ns_value($row,'TIPO_INSTALACION'),'Instalación'=>ns_value($row,'INSTALACION'),'TAG'=>ns_value($row,'TAG'),'Descripción'=>ns_value($row,'DESCRIPCION'),'Total alarmas'=>(int)ns_value($row,'TOTAL_ALARMAS'),'Campo externo'=>ns_value($row,'CAMPO_EXT'),'Comentario'=>$comment,'Última gestión'=>$comment?$user.' · '.$saved:'—']); ?><tr><td class="nsCheckCell"><?php if($reportReady)echo ns_report_pick(ns_report_key('seguimiento',[ns_value($row,'SEMANA_DESDE'),ns_value($row,'TIPO_INSTALACION'),ns_value($row,'INSTALACION'),ns_value($row,'TAG')]),'row','Seguimiento · '.ns_value($row,'INSTALACION').' · '.ns_value($row,'TAG'),$payload); ?></td><td><?php echo h($weekLabel); ?></td><td><span class="nsType <?php echo h(ns_type_class(ns_value($row,'TIPO_INSTALACION'))); ?>"><?php echo h(ns_value($row,'TIPO_INSTALACION')); ?></span></td><td><b><?php echo h(ns_value($row,'INSTALACION')); ?></b></td><td><?php echo h(ns_value($row,'TAG')); ?></td><td><?php echo h(ns_value($row,'DESCRIPCION')); ?></td><td data-sort="<?php echo (int)ns_value($row,'TOTAL_ALARMAS'); ?>"><span class="nsTotal"><?php echo ns_num(ns_value($row,'TOTAL_ALARMAS')); ?></span></td><td><?php echo h(ns_value($row,'CAMPO_EXT')?:'—'); ?></td><td><div style="display:flex;align-items:center;gap:8px"><?php echo ns_render_comment_button($row,$weekLabel,$canUseComments); ?><span class="nsCommentPreview" data-comment-preview><?php echo h($comment?:'Sin comentario'); ?></span></div></td><td><?php echo $comment?h($user.' · '.$saved):'—'; ?></td></tr><?php endforeach;endif; ?></tbody></table></div></section>
<?php endif; ?></main></div><?php if($ready&&$canUseComments)ns_render_comment_modal(permissions_can('comments.create')); ?><script src="assets/js/app.js?v=20260826-ns3"></script><script src="assets/js/novedades_semanales.js?v=20260826-select-all-1"></script></body></html>
